  "Drag the coloured handles to move, rotate or scale. Drag empty space to orbit; pinch with two fingers to zoom and pan.": "Ziehen Sie die farbigen Griffe zum Verschieben, Drehen oder Skalieren. Ziehen Sie einen leeren Bereich zum Umkreisen; mit zwei Fingern zoomen und verschieben Sie die Ansicht.",
